#!/usr/bin/env python3
"""Wrap gen_theme.py output into crates/t3code-ui/src/theme/tokens.rs."""
import subprocess, sys, re
out = subprocess.run([sys.executable, 'tools/gen_theme.py', '../t3code/apps/web/src/index.css'],
                     capture_output=True, text=True, check=True).stdout
light, dark = out.split('---DARK---')
def dedent(b):
    return '\n'.join(l for l in b.splitlines() if l.strip())
header = '''// @generated by tools/emit_theme.py from ../t3code/apps/web/src/index.css
// Do not edit by hand: re-run the generator instead.
//
// Every constant below is the resolved value of one t3code CSS token, so the
// GPUI port paints with the same numbers the web app paints with.
#![allow(dead_code)]

use crate::theme::Rgba;

/// Light theme. Mirrors `:root` in t3code's index.css.
pub mod light {
    use super::Rgba;
LIGHT
}

/// Dark theme. Mirrors `@variant dark` inside `:root`.
pub mod dark {
    use super::Rgba;
DARK
}
'''.replace('LIGHT', dedent(light)).replace('DARK', dedent(dark))
import os
path = 'crates/t3code-ui/src/theme/tokens.rs'
os.makedirs(os.path.dirname(path), exist_ok=True)
open(path, 'w').write(header)
n = len(re.findall(r'pub const ', header))
print(f'wrote {path} ({n} constants)')
